-- Multilingual Vamsha relationship lexicon.
-- Generated from Family_Relationship_Words-languages.numbers.

alter table public.relationship_terms
  add column if not exists canonical_code text,
  add column if not exists language_tag text,
  add column if not exists generation text,
  add column if not exists variants text[] not null default array[]::text[],
  add column if not exists source_name text,
  add column if not exists source_type text not null default 'manual',
  add column if not exists updated_at timestamptz not null default now();

update public.relationship_terms
set canonical_code = lower(regexp_replace(canonical_meaning, '[^a-zA-Z0-9]+', '_', 'g'))
where canonical_code is null;

update public.relationship_terms
set language_tag = case language
  when 'Tamil' then 'ta-IN'
  when 'Malayalam' then 'ml-IN'
  when 'Telugu' then 'te-IN'
  when 'Kannada' then 'kn-IN'
  when 'Hindi' then 'hi-IN'
  else 'und'
end
where language_tag is null;

alter table public.relationship_terms
  alter column canonical_code set not null,
  alter column language_tag set not null;

create unique index if not exists relationship_terms_code_language_term_uidx
  on public.relationship_terms (canonical_code, language_tag, term);

insert into public.relationship_terms (
  term,
  canonical_meaning,
  canonical_code,
  language,
  language_tag,
  generation,
  variants,
  source_name,
  source_type
)
