alter table public.relationship_terms enable row level security;

drop policy if exists "Relationship terms are readable reference data"
  on public.relationship_terms;

create policy "Relationship terms are readable reference data"
  on public.relationship_terms
  for select
  to anon, authenticated
  using (true);

revoke all on table public.relationship_terms from anon, authenticated;
grant select on table public.relationship_terms to anon, authenticated;
grant select, insert, update, delete on table public.relationship_terms
  to service_role;
